    explanation: "**SAT Pattern: Triangle Angle Sum**\n\n**Choice B is correct.**\n\n**The Fast Way (~10s):** The three angles add to $180^\\circ$, so angle $R = 180^\\circ - 47^\\circ - 68^\\circ = 65^\\circ$.\n\n**The Full Solution:**\nStep 1: The interior angles of any triangle sum to $180^\\circ$.\nStep 2: With angle $P = 47^\\circ$ and angle $Q = 68^\\circ$, angle $R = 180^\\circ - (47^\\circ + 68^\\circ) = 180^\\circ - 115^\\circ = 65^\\circ$.\nStep 3: Check: $47 + 68 + 65 = 180$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice A ($55^\\circ$): arithmetic slip in the subtraction; the running total of the two known angles was misread.\n* Choice C ($75^\\circ$): averages $47$ and $68$ instead of using the angle-sum rule.\n* Choice D ($115^\\circ$): reports the sum of the two known angles, which is the supplement of the answer, not angle $R$.\n\n**Test Day Takeaway:** Given two angles of a triangle, the third is $180^\\circ$ minus their sum. Watch for the supplement of the answer planted as a distractor.",
