    explanation: "**SAT Pattern: Degrees to Radians**\n\n**Choice C is correct.**\n\n**The Fast Way (~5s):** $90^\\circ$ is a quarter turn, and a full turn is $2\\pi$ radians, so $90^\\circ = \\frac{2\\pi}{4} = \\frac{\\pi}{2}$.\n\n**The Full Solution:**\nStep 1: Multiply by the conversion factor $\\frac{\\pi}{180^\\circ}$.\nStep 2: $90^\\circ \\times \\frac{\\pi}{180^\\circ} = \\frac{90\\pi}{180} = \\frac{\\pi}{2}$ radians.\nStep 3: Check the reverse: $\\frac{\\pi}{2} \\times \\frac{180^\\circ}{\\pi} = 90^\\circ$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice A ($\\frac{\\pi}{6}$): this is the radian measure of $30^\\circ$.\n* Choice B ($\\frac{\\pi}{4}$): this is the radian measure of $45^\\circ$.\n* Choice D ($\\pi$): this is the radian measure of $180^\\circ$, twice the correct value.\n\n**Test Day Takeaway:** To go from degrees to radians, multiply by $\\frac{\\pi}{180^\\circ}$. The landmark values $\\frac{\\pi}{6}, \\frac{\\pi}{4}, \\frac{\\pi}{3}, \\frac{\\pi}{2}$ map to $30^\\circ, 45^\\circ, 60^\\circ, 90^\\circ$.",
