    explanation: "**SAT Pattern: Triangle Inequality**\n\n**Choice C is correct.**\n\n**The Fast Way (~15s):** Add the two shorter sides. If their sum is greater than the longest side, the triangle exists. For $5, 7, 11$: $5+7=12>11$, so choice C works.\n\n**The Full Solution:**\nStep 1: The Triangle Inequality requires the two shorter sides to sum to strictly more than the longest side.\nStep 2: Test each set against its largest value.\nChoice C ($5, 7, 11$): $5+7=12>11$. The triangle exists.\n\n**Why the wrong answers are tempting:**\n* Choice A ($2, 3, 8$): $2+3=5$, which is $<8$. Fails.\n* Choice B ($4, 4, 9$): $4+4=8$, which is $<9$. Fails.\n* Choice D ($1, 2, 3$): $1+2=3$ exactly, which collapses the triangle into a straight line (degenerate). The sum must be strictly greater.\n\n**Test Day Takeaway:** Only one check matters: do the two smallest sides sum to more than the largest? Strictly greater means a real triangle; equal means a flat, degenerate one.",
