    correctAnswer: 'A',
    explanation: "**SAT Pattern: Sphere Volume**\n\n**Choice A is correct.**\n\n**The Fast Way (~10s):** $V=\\frac{4}{3}\\pi r^3=\\frac{4}{3}\\pi(27)=36\\pi$ cubic inches.\n\n**The Full Solution:**\nStep 1: The volume of a sphere is $V=\\frac{4}{3}\\pi r^3$ (Reference Sheet formula).\nStep 2: With $r=3$, $r^3=27$, so $V=\\frac{4}{3}\\pi(27)=\\frac{108\\pi}{3}=36\\pi$ cubic inches.\n\n**Why the wrong answers are tempting:**\n* Choice B ($27\\pi$): used $\\pi r^3$ and dropped the $\\frac{4}{3}$ factor.\n* Choice C ($\\frac{108\\pi}{3}$): numerically equal to $36\\pi$, but the SAT lists the simplified form as the correct answer.\n* Choice D ($108\\pi$): used $4\\pi r^3$, forgetting to divide by $3$.\n\n**Test Day Takeaway:** Sphere volume is $\\frac{4}{3}\\pi r^3$. The $\\frac{4}{3}$ is the factor students drop or invert under pressure — and always simplify, since the unsimplified form is a planted distractor.",
