    explanation: "**SAT Pattern: Radian Measure of a Full Circle**\n\n**Choice B is correct.**\n\n**The Fast Way (~5s):** A full rotation is $360^\\circ$, which equals $2\\pi$ radians by definition.\n\n**The Full Solution:**\nStep 1: Convert a full turn from degrees to radians: $360^\\circ \\times \\frac{\\pi}{180^\\circ}=2\\pi$ radians.\nStep 2: This matches the definition — the radian measure of a full circle is the circumference over the radius, $\\frac{2\\pi r}{r}=2\\pi$.\n\n**Why the wrong answers are tempting:**\n* Choice A ($\\pi$): that is half a rotation, $180^\\circ$.\n* Choice C ($360$): the degree measure, not the radian measure — wrong units.\n* Choice D ($\\frac{\\pi}{2}$): a quarter rotation, $90^\\circ$.\n\n**Test Day Takeaway:** $2\\pi$ radians $=360^\\circ$. Anchor on this one fact and you can convert any radian-degree pair instantly.",
