    explanation: "**SAT Pattern: Circle Equation Standard Form**\n\n**Choice A is correct.**\n\n**The Fast Way (~10s):** Standard form is $(x-h)^2+(y-k)^2=r^2$. With $h=2$, $k=-3$, $r=4$: $(x-2)^2+(y+3)^2=16$.\n\n**The Full Solution:**\nStep 1: A circle with center $(h,k)$ and radius $r$ is $(x-h)^2+(y-k)^2=r^2$.\nStep 2: Substitute the center $(2,-3)$: $(x-2)^2+(y-(-3))^2=4^2$.\nStep 3: Simplify: $(x-2)^2+(y+3)^2=16$.\n\n**Why the wrong answers are tempting:**\n* Choice B ($(x+2)^2+(y-3)^2=16$): flipped both signs, giving center $(-2,3)$.\n* Choice C ($(x-2)^2+(y+3)^2=4$): left $r=4$ on the right instead of $r^2=16$.\n* Choice D ($(x-2)^2+(y-3)^2=16$): wrote $(y-3)$ instead of $(y-(-3))=(y+3)$.\n\n**Test Day Takeaway:** The signs inside the equation are the opposite of the center coordinates, and the right side is $r^2$, not $r$. Center $(2,-3)$ gives $(x-2)^2+(y+3)^2$.",
    calculatorAllowed: true,
