    explanation: "**SAT Pattern: Cone Volume**\n\n**The correct answer is $21$.**\n\n**The Fast Way (~10s):** $V=\\frac{1}{3}\\pi r^2 h=\\frac{1}{3}\\pi(9)(7)=21\\pi$. The coefficient of $\\pi$ is $21$.\n\n**The Full Solution:**\nStep 1: Cone volume is $V=\\frac{1}{3}\\pi r^2 h$ (Reference Sheet formula).\nStep 2: With $r=3$ and $h=7$: $V=\\frac{1}{3}\\pi(3)^2(7)=\\frac{1}{3}\\pi(9)(7)=\\frac{63\\pi}{3}=21\\pi$ cubic centimeters.\nStep 3: The question asks for the number multiplying $\\pi$, which is $21$.\n\n**Common Mistakes:** Dropping the $\\frac{1}{3}$ gives $63$ (the cylinder volume); forgetting to square the radius gives $7$; entering $21\\pi$ instead of just the coefficient $21$.\n\n**Test Day Takeaway:** A cone is $\\frac{1}{3}$ of the cylinder with the same base and height. That $\\frac{1}{3}$ factor (shared with pyramids) is the most-forgotten piece in SAT geometry.",
