    correctAnswer: 'B',
    explanation: "**SAT Pattern: Ladder Pythagorean**\n\n**Choice B is correct.**\n\n**The Fast Way (~10s):** Recognize $8$-$15$-$17$ as a Pythagorean triple. With legs $8$ and $h$ and hypotenuse $17$, the height is $15$.\n\n**The Full Solution:**\nStep 1: The ladder is the hypotenuse ($17$), the ground distance is one leg ($8$), and the wall height $h$ is the other leg.\nStep 2: $h^2+8^2=17^2 \\Rightarrow h^2=289-64=225$.\nStep 3: $h=\\sqrt{225}=15$ feet.\n\n**Why the wrong answers are tempting:**\n* Choice A ($9$): subtracted directly, $17-8=9$, ignoring the squares.\n* Choice C ($\\sqrt{353}$): added the squares, $\\sqrt{17^2+8^2}$, treating $h$ as the hypotenuse.\n* Choice D ($12$): a rough guess near half the ladder length, with no computation.\n\n**Test Day Takeaway:** Ladder problems are Pythagorean: the ladder is the hypotenuse; the ground distance and wall height are the legs. Memorize $8$-$15$-$17$ — it appears constantly.",
