    correctAnswer: 'B',
    explanation: "**SAT Pattern: Arc Length**\n\n**Choice B is correct.**\n\n**The Fast Way (~15s):** $72^\\circ$ is $\\frac{72}{360}=\\frac{1}{5}$ of the circle. The circumference is $2\\pi(10)=20\\pi$, and one-fifth of that is $4\\pi$.\n\n**The Full Solution:**\nStep 1: Arc length is the central-angle fraction of the circumference: $\\text{arc}=\\frac{\\theta}{360^\\circ}\\times 2\\pi r$.\nStep 2: Substitute: $\\frac{72}{360}\\times 2\\pi(10)=\\frac{1}{5}\\times 20\\pi=4\\pi$ cm.\n\n```seva-figure\n{\"type\":\"circleWithSector\",\"params\":{\"centralAngle\":72,\"angleLabel\":\"72\u00b0\",\"radius\":10,\"showRadiusLabel\":true,\"showAngleArc\":true},\"caption\":\"A $72\u00b0$ central angle cuts off one-fifth of the circle, so the arc is one-fifth of the circumference.\"}\n```\n\n**Why the wrong answers are tempting:**\n* Choice A ($2\\pi$): used $\\frac{1}{10}$ of the circumference instead of $\\frac{1}{5}$.\n* Choice C ($7.2\\pi$): used $\\frac{72}{100}$ as the fraction instead of $\\frac{72}{360}$.\n* Choice D ($20\\pi$): reported the full circumference, never scaling by $\\frac{\\theta}{360}$.\n\n**Test Day Takeaway:** Arc length $=\\frac{\\theta}{360}\\times 2\\pi r$ in degrees (or $r\\theta$ in radians). Always pin down what fraction of the full circle the angle is.",
    calculatorAllowed: true,
    tags: [],
    sourceStyleRef: 'arc-sector-computation',
    authoredBy: 'performsat-engine',
    createdAt: '2026-02-28',
