    explanation: "**SAT Pattern: Translate to Equation**\n\n**Choice C is correct.**\n\n**The Fast Way (~25s):** Let $K = x$. The angles sum to $180^\\circ$: $3x + x + (x + 20) = 180$, so $5x = 160$ and $x = 32$. Then $J = 3x = 96$.\n\n**The Full Solution:**\nStep 1: Let $K = x$. Then $J = 3x$ and $L = x + 20$.\nStep 2: The three angles of a triangle sum to $180^\\circ$: $3x + x + (x + 20) = 180$.\nStep 3: Combine: $5x + 20 = 180 \\Rightarrow 5x = 160 \\Rightarrow x = 32$.\nStep 4: The question asks for $J$, so $J = 3x = 3(32) = 96^\\circ$. Check: $96 + 32 + 52 = 180$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice A ($32$): reports angle $K = x$ instead of $J$.\n* Choice B ($52$): reports angle $L = x + 20$ instead of $J$.\n* Choice D ($108$): drops the $+20$ when summing, gets $x = 36$, then $3x = 108$.\n\n**Test Day Takeaway:** When angles are given relative to one another, name one angle as the variable, write the rest in terms of it, sum to $180^\\circ$, then reread which angle is actually requested.",
