    difficulty: 'medium',
    type: 'multiple-choice',
    question: 'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle has length $7$. What is the length of the hypotenuse?',
    choices: [
      // distractor: uses 45-45-90 hypotenuse ratio
      { id: 'A', text: '$7\\sqrt{2}$' },
      // distractor: gives the long leg instead of the hypotenuse
      { id: 'B', text: '$7\\sqrt{3}$' },
      { id: 'C', text: '$14$' },
      // distractor: divides instead of multiplying
      { id: 'D', text: '$\\frac{7\\sqrt{3}}{3}$' },
    ],
    correctAnswer: 'C',
    explanation: "**SAT Pattern: 30-60-90 Triangle**\n\n**Choice C is correct.**\n\n**The Fast Way (~5s):** In a $30^\\circ$-$60^\\circ$-$90^\\circ$ triangle the hypotenuse is twice the side opposite $30^\\circ$: $2 \\times 7 = 14$.\n\n**The Full Solution:**\nStep 1: The $30^\\circ$-$60^\\circ$-$90^\\circ$ side ratio is $1 : \\sqrt{3} : 2$, opposite $30^\\circ$, $60^\\circ$, and $90^\\circ$ respectively.\nStep 2: The side opposite $30^\\circ$ is the short leg, equal to $7$, so it matches the \"$1$\" in the ratio.\nStep 3: The hypotenuse matches the \"$2$\": hypotenuse $= 2 \\times 7 = 14$. Check: $7^2 + (7\\sqrt{3})^2 = 49 + 147 = 196 = 14^2$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice A ($7\\sqrt{2}$): uses the $45^\\circ$-$45^\\circ$-$90^\\circ$ hypotenuse factor $\\sqrt{2}$.\n* Choice B ($7\\sqrt{3}$): gives the long leg (opposite $60^\\circ$) instead of the hypotenuse.\n* Choice D ($\\frac{7\\sqrt{3}}{3}$): divides by $\\sqrt{3}$ instead of doubling.\n\n**Test Day Takeaway:** $30^\\circ$-$60^\\circ$-$90^\\circ$ ratios are $1 : \\sqrt{3} : 2$. The hypotenuse is always twice the short leg; the long leg is the short leg times $\\sqrt{3}$.",
    calculatorAllowed: true,
    tags: [],
    sourceStyleRef: 'special-triangle-ratio',
    authoredBy: 'performsat-engine',
    createdAt: '2026-02-28',
