    skills: ['similar-triangles'],
    difficulty: 'medium',
    type: 'multiple-choice',
    question: 'A $6$-foot-tall person casts a $4$-foot shadow at the same time a flagpole casts a $20$-foot shadow. How tall, in feet, is the flagpole?',
    choices: [
      // distractor: multiplies 6 × 4 instead of using proportion
      { id: 'A', text: '$24$' },
      { id: 'B', text: '$30$' },
      // distractor: adds the differences instead of setting up proportion
      { id: 'C', text: '$18$' },
      // distractor: inverts the ratio (4/6 × 20)
      { id: 'D', text: '$13.3$' },
    ],
    correctAnswer: 'B',
    explanation: "**SAT Pattern: Shadow Similar Triangles**\n\n**Choice B is correct.**\n\n**The Fast Way (~10s):** Same sun angle makes the triangles similar, so $\\frac{\\text{height}}{\\text{shadow}}$ is constant: $\\frac{6}{4} = \\frac{h}{20} \\Rightarrow h = 30$.\n\n**The Full Solution:**\nStep 1: At one instant the sun's angle creates two similar right triangles: the person ($6$ ft tall, $4$-ft shadow) and the flagpole ($h$ ft tall, $20$-ft shadow).\nStep 2: Similar triangles have proportional sides: $\\frac{6}{4} = \\frac{h}{20}$.\nStep 3: Cross-multiply: $4h = 120 \\Rightarrow h = 30$ feet. Check: $\\frac{30}{20} = \\frac{3}{2} = \\frac{6}{4}$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice A ($24$): multiplies $6 \\times 4$ and never uses the $20$-ft shadow.\n* Choice C ($18$): combines the lengths additively instead of proportionally.\n* Choice D ($13.3$): flips the ratio to $\\frac{4}{6} \\times 20$.\n\n**Test Day Takeaway:** Shadow problems are similar triangles. Set \"object height over its shadow\" equal for both objects, then cross-multiply.",
    calculatorAllowed: true,
    tags: [],
    sourceStyleRef: 'real-world-similar-triangles',
