    difficulty: 'medium',
    type: 'multiple-choice',
    question: 'A square pyramid has a base side length of $6$ m and a height of $10$ m. What is the volume, in cubic meters?',
    choices: [
      { id: 'A', text: '$120$' },
      // distractor: multiplies (1/2)(36)(10) using triangle area instead of square
      { id: 'B', text: '$180$' },
      // distractor: omits the (1/3) factor
      { id: 'C', text: '$360$' },
      // distractor: uses side 6 as edge length instead of base side
      { id: 'D', text: '$60$' },
    ],
    correctAnswer: 'A',
    explanation: "**SAT Pattern: Square Pyramid Volume**\n\n**Choice A is correct.**\n\n**The Fast Way (~10s):** $V = \\frac{1}{3} s^2 h = \\frac{1}{3}(36)(10) = 120$.\n\n**The Full Solution:**\nStep 1: Pyramid volume is $V = \\frac{1}{3} \\times (\\text{base area}) \\times (\\text{height})$.\nStep 2: The square base has area $s^2 = 6^2 = 36$.\nStep 3: $V = \\frac{1}{3}(36)(10) = \\frac{360}{3} = 120$ cubic meters.\n\n**Why the wrong answers are tempting:**\n* Choice B ($180$): uses $\\frac{1}{2}$ instead of $\\frac{1}{3}$, confusing the triangle and pyramid factors.\n* Choice C ($360$): computes $s^2 h$ but drops the $\\frac{1}{3}$, giving the full prism volume.\n* Choice D ($60$): treats the side $6$ as the height somewhere instead of squaring the base.\n\n**Test Day Takeaway:** Pyramid (and cone) volume $= \\frac{1}{3} \\times (\\text{base area}) \\times (\\text{height})$. The $\\frac{1}{3}$ always applies to tapered solids.",
