    correctAnswer: 'A',
    explanation: "**SAT Pattern: Right Triangle — Trig Ratios**\n\n**Choice A is correct.**\n\n**The Fast Way (~15s):** The right angle is at $C$, so $AB=13$ is the hypotenuse and $BC=5$ is opposite angle $A$. By SOH, $\\sin A = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{5}{13}$.\n\n**The Full Solution:**\nStep 1: The hypotenuse sits opposite the right angle. With the right angle at $C$, the hypotenuse is $AB=13$.\nStep 2: The side opposite angle $A$ is $BC=5$.\nStep 3: $\\sin A = \\frac{BC}{AB} = \\frac{5}{13}$.\n\nThe third side is $AC = \\sqrt{13^2 - 5^2} = \\sqrt{144} = 12$ (the $5$-$12$-$13$ triple), confirming the setup.\n\n**Why the wrong answers are tempting:**\n* Choice B ($\\frac{12}{13}$): uses the adjacent side $AC=12$ — that ratio is $\\cos A$, not $\\sin A$.\n* Choice C ($\\frac{5}{12}$): uses opposite over adjacent — that is $\\tan A$.\n* Choice D ($\\frac{13}{5}$): inverts the correct ratio, giving $\\csc A$.\n\n**Test Day Takeaway:** Find the hypotenuse first (it faces the right angle), then for $\\sin$ take the side opposite the named angle over the hypotenuse.",
