    explanation: "**SAT Pattern: Right Triangle — Trig Ratios**\n\n**Choice C is correct.**\n\n**The Fast Way (~25s):** With the right angle at $A$, $BC$ is the hypotenuse and $AB$ is adjacent to $B$, so $\\cos B = \\frac{AB}{BC} = \\frac{18}{BC} = \\frac{3}{5}$. Cross-multiply: $BC = \\frac{18 \\cdot 5}{3} = 30$.\n\n**The Full Solution:**\nStep 1: The right angle is at $A$, so $BC$ is the hypotenuse.\nStep 2: For angle $B$, the adjacent leg is $AB=18$, so $\\cos B = \\frac{AB}{BC} = \\frac{3}{5}$.\nStep 3: Solve $\\frac{18}{BC} = \\frac{3}{5} \\Rightarrow 3 \\cdot BC = 90 \\Rightarrow BC = 30$.\n\nCheck: $AC = \\sqrt{30^2 - 18^2} = \\sqrt{576} = 24$, so the sides $18$-$24$-$30$ are the $3$-$4$-$5$ triple scaled by $6$, and $\\cos B = \\frac{18}{30} = \\frac{3}{5}$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice A ($5$): reports the ratio's denominator without scaling it to match $AB=18$.\n* Choice B ($24$): gives the third side $AC$, not the requested hypotenuse $BC$.\n* Choice D ($10.8$): multiplies $18 \\cdot \\frac{3}{5}$ instead of $18 \\cdot \\frac{5}{3}$ — shrinks the hypotenuse instead of growing it.\n\n**Test Day Takeaway:** When a trig ratio gives the adjacent piece and you want the hypotenuse, set up $\\frac{\\text{given leg}}{\\text{hypotenuse}} = \\frac{\\text{ratio numerator}}{\\text{ratio denominator}}$ and solve.",
