    explanation: "**SAT Pattern: Right Triangle — Trig Ratios**\n\n**Choice A is correct.**\n\n**The Fast Way (~15s):** $\\sin M = \\frac{24}{25}$ is the $7$-$24$-$25$ triple, so the adjacent side is $7$. Therefore $\\cos M = \\frac{7}{25}$.\n\n**The Full Solution:**\nStep 1: $\\sin M = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{24}{25}$, so opposite $=24$ and hypotenuse $=25$.\nStep 2: The adjacent side is $\\sqrt{25^2 - 24^2} = \\sqrt{49} = 7$.\nStep 3: $\\cos M = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{7}{25}$.\n\nIdentity check: $\\cos^2 M = 1 - \\frac{576}{625} = \\frac{49}{625}$, so $\\cos M = \\frac{7}{25}$. $\\checkmark$\n\n**Why the wrong answers are tempting:**\n* Choice B ($\\frac{24}{7}$): uses opposite over adjacent — that is $\\tan M$.\n* Choice C ($\\frac{1}{25}$): subtracts raw values, $1 - \\frac{24}{25}$. The Pythagorean identity uses squares, not the ratios themselves.\n* Choice D ($\\frac{7}{24}$): uses adjacent over opposite — that is $\\cot M$.\n\n**Test Day Takeaway:** Given one ratio, recognize the Pythagorean triple to read off the missing side, or use $\\sin^2 + \\cos^2 = 1$ (with squares).",
