    difficulty: 'hard',
    type: 'fill-in',
    question: 'In right triangle $UVW$, the right angle is at vertex $V$. If $\\tan U = \\dfrac{5}{12}$ and $UV = 36$, what is the perimeter of triangle $UVW$?',
    correctAnswer: '90',
    explanation: "**SAT Pattern: Right Triangle — Trig Ratios**\n\n**The correct answer is $90$.**\n\n**The Fast Way (~30s):** $\\tan U = \\frac{VW}{UV} = \\frac{5}{12}$ with $UV = 36 = 12 \\cdot 3$, so the sides are the $5$-$12$-$13$ triple scaled by $3$: legs $15$ and $36$, hypotenuse $39$. Perimeter $= 15 + 36 + 39 = 90$.\n\n**The Full Solution:**\nStep 1: The right angle is at $V$, so $UW$ is the hypotenuse. For angle $U$, opposite $= VW$ and adjacent $= UV$.\nStep 2: $\\tan U = \\frac{VW}{UV} = \\frac{5}{12}$, so $\\frac{VW}{36} = \\frac{5}{12} \\Rightarrow VW = \\frac{36 \\cdot 5}{12} = 15$.\nStep 3: $UW = \\sqrt{36^2 + 15^2} = \\sqrt{1521} = 39$.\nStep 4: Perimeter $= 36 + 15 + 39 = 90$.\n\nThe sides $15$-$36$-$39$ are the $5$-$12$-$13$ triple times $3$. $\\checkmark$\n\n**Common Mistakes:** Adding only the legs ($36 + 15 = 51$) and dropping the hypotenuse; mixing scaled and unscaled sides ($15 + 36 + 13 = 64$); treating $\\frac{5}{12}$ as literal side lengths instead of a ratio.\n\n**Test Day Takeaway:** Recognize $\\frac{5}{12}$ as the $5$-$12$-$13$ triple, find the scale factor from the given side ($36/12 = 3$), then scale all three sides.",
    calculatorAllowed: true,
    tags: [],
    sourceStyleRef: 'right-triangle-trig-ratios',
    authoredBy: 'performsat-engine',
