    correctAnswer: 'A',
    explanation: "**SAT Pattern: Circle in General Form**\n\n**Choice A is correct.**\n\n**The Fast Way (~20s):** Complete the square: $(x-2)^2 + (y-3)^2 = 12 + 4 + 9 = 25$. The center is $(2, 3)$.\n\n**The Full Solution:**\nStep 1: Group the variables: $(x^2 - 4x) + (y^2 - 6y) = 12$.\nStep 2: Complete each square — add $(\\frac{-4}{2})^2 = 4$ and $(\\frac{-6}{2})^2 = 9$ to both sides: $(x-2)^2 + (y-3)^2 = 12 + 4 + 9 = 25$.\nStep 3: Standard form $(x-h)^2 + (y-k)^2 = r^2$ gives center $(h, k) = (2, 3)$ and $r = 5$.\n\n**Why the wrong answers are tempting:**\n* Choice B ($(-2, -3)$): flips both signs — the center keeps the signs read directly from $(x-h)$, $(y-k)$.\n* Choice C ($(4, 6)$): uses the linear coefficients $4$ and $6$ directly without halving and negating.\n* Choice D ($(2, -3)$): flips just the $y$-sign.\n\n**Test Day Takeaway:** From $x^2 + y^2 + Bx + Cy + D = 0$, the center is $\\left(-\\frac{B}{2}, -\\frac{C}{2}\\right)$ — halve and negate the linear coefficients.",
