    explanation: "**SAT Pattern: Right Triangle — Pythagorean**\n\n**The correct answer is $12$.**\n\n**The Fast Way (~15s):** A diagonal makes the length and width the legs of a right triangle with the diagonal as hypotenuse. $9$ and $15$ scale the $3$-$5$ part of $3$-$4$-$5$ by $3$, so it's $9$-$12$-$15$: the width is $12$.\n\n```seva-figure\n{\"type\":\"rightTriangle\",\"params\":{\"vertices\":[[0,0],[9,0],[9,12.0]],\"sideLabels\":[\"9\",\"12\",\"15\"],\"rightAngleVertex\":1},\"caption\":\"Legs 9 and 12 — hypotenuse 15.\"}\n```\n\n**The Full Solution:**\nStep 1: The sides and diagonal satisfy $L^2 + W^2 = d^2$ with $L = 9$, $d = 15$.\nStep 2: $9^2 + W^2 = 15^2 \\Rightarrow 81 + W^2 = 225$.\nStep 3: $W^2 = 144$, so $W = \\sqrt{144} = 12$.\n\nVerification: $9$-$12$-$15$ is the $3$-$4$-$5$ triple scaled by $3$. $\\checkmark$\n\n**Common Mistakes:** Treating the diagonal as a leg ($9^2 + 15^2$); subtracting lengths directly to get $6$; stopping at $W^2 = 144$.\n\n**Test Day Takeaway:** A rectangle's diagonal is always the HYPOTENUSE of a right triangle whose legs are the length and width. Identify the hypotenuse first, then apply the theorem.",
