    explanation: "**SAT Pattern: Cylinder Volume**\n\n**The correct answer is $75$.**\n\n**The Fast Way (~10s):** $V=\\pi r^2 h = \\pi(5)^2(3)=75\\pi$, so the coefficient $k=75$.\n\n**The Full Solution:**\nStep 1: Use $V=\\pi r^2 h = \\pi(5)^2(3)=\\pi(25)(3)=75\\pi$ cubic centimeters.\nStep 2: The volume is written as $k\\pi$, so matching $75\\pi = k\\pi$ gives $k=75$.\n\n**Common Mistakes:** Reporting $75\\pi$ when the question asks only for the coefficient $k$; forgetting to square the radius and computing $5\\cdot 3=15$; using the cone formula and getting $\\frac{1}{3}(75)=25$.\n\n**Test Day Takeaway:** When a volume is given as $k\\pi$, factor out $\\pi$ and report only the numeric coefficient.",
    calculatorAllowed: true,
