    question: 'The volume of a right circular cylinder is $48\\pi$ cubic inches and its height is $3$ inches. What is the radius, in inches, of the cylinder?',
    correctAnswer: '4',
    explanation: "**SAT Pattern: Cylinder Volume**\n\n**The correct answer is $4$.**\n\n**The Fast Way (~15s):** $V=\\pi r^2 h \\Rightarrow 48\\pi = \\pi r^2(3) \\Rightarrow r^2=16 \\Rightarrow r=4$.\n\n**The Full Solution:**\nStep 1: From $V=\\pi r^2 h$, substitute: $48\\pi = \\pi r^2(3)$.\nStep 2: Divide both sides by $\\pi$: $48 = 3r^2$, so $r^2=16$.\nStep 3: Take the positive square root (a radius must be positive): $r=4$.\nStep 4: Check: $\\pi(4)^2(3)=\\pi(16)(3)=48\\pi$. $\\checkmark$\n\n**Common Mistakes:** Stopping at $r^2=16$ and reporting $16$ instead of taking the square root; forgetting the final square root step entirely.\n\n**Test Day Takeaway:** Solving for a radius always ends in a square root: $r^2=\\frac{V}{\\pi h}$, then $r=\\sqrt{r^2}$.",
