    explanation: "**SAT Pattern: Cylinder Volume**\n\n**Choice A is correct.**\n\n**The Fast Way (~15s):** In $V=\\pi r^2 h$ the radius is squared, so doubling $r$ multiplies the volume by $2^2=4$.\n\n**The Full Solution:**\nStep 1: Original volume: $V_1=\\pi r^2 h$.\nStep 2: Replace $r$ with $2r$: $V_2=\\pi(2r)^2 h=\\pi(4r^2)h=4\\pi r^2 h=4V_1$.\nStep 3: So the volume is multiplied by $4$.\n\n**Why the wrong answers are tempting:**\n* Choice B ($2$): doubled the radius but forgot the square.\n* Choice C ($8$): used a cube factor — that applies only if a length scaled all three dimensions, not a single radius.\n* Choice D ($1$): assumed the scaling somehow cancels.\n\n**Test Day Takeaway:** When a length scales by $k$, any term it is squared in scales by $k^2$. Here the radius is squared, so doubling it gives a factor of $4$.",
