    explanation: "**SAT Pattern: Cylinder Volume**\n\n**Choice A is correct.**\n\n**The Fast Way (~20s):** Same height, so the volume ratio is the square of the radius ratio: $\\left(\\frac{1}{2}\\right)^2=\\frac{1}{4}$, giving $1:4$.\n\n**The Full Solution:**\nStep 1: Let $r_B=r$ so $r_A=\\frac{r}{2}$, with $h_A=h_B=h$.\nStep 2: $V_A=\\pi\\left(\\frac{r}{2}\\right)^2 h=\\pi\\cdot\\frac{r^2}{4}\\cdot h=\\frac{\\pi r^2 h}{4}$ and $V_B=\\pi r^2 h$.\nStep 3: $\\frac{V_A}{V_B}=\\frac{\\pi r^2 h/4}{\\pi r^2 h}=\\frac{1}{4}$, so $V_A:V_B=1:4$.\n\n**Why the wrong answers are tempting:**\n* Choice B ($1:2$): used the radius ratio directly instead of squaring it.\n* Choice C ($1:8$): cubed the ratio — that applies only if every dimension halved.\n* Choice D ($2:1$): inverted the ratio, giving $V_B:V_A$ instead of $V_A:V_B$.\n\n**Test Day Takeaway:** With equal heights, the cylinder volume ratio equals the square of the radius ratio. Halving the radius cuts the volume to $\\frac{1}{4}$.",
