    type: 'fill-in',
    question: 'A cylindrical tank with a radius of $3$ feet and a height of $10$ feet is filled with water at a rate of $30\\pi$ cubic feet per minute. How many minutes does it take to fill the tank completely?',
    correctAnswer: '3',
    explanation: "**SAT Pattern: Cylinder Volume**\n\n**The correct answer is $3$.**\n\n**The Fast Way (~20s):** Volume $=\\pi(3)^2(10)=90\\pi$ cubic feet; time $=\\frac{90\\pi}{30\\pi}=3$ minutes.\n\n**The Full Solution:**\nStep 1: Find the tank's volume: $V=\\pi r^2 h=\\pi(3)^2(10)=90\\pi$ cubic feet.\nStep 2: Divide by the fill rate: time $=\\frac{V}{\\text{rate}}=\\frac{90\\pi}{30\\pi}=3$ minutes.\nStep 3: Check: in $3$ minutes at $30\\pi$ cubic feet per minute, $3\\times 30\\pi=90\\pi$ cubic feet enters — exactly the tank's volume. $\\checkmark$\n\n**Common Mistakes:** Reporting $90\\pi$ (the volume, not the time); multiplying instead of dividing by the rate; forgetting to square the radius, which would give $\\frac{30\\pi}{30\\pi}=1$ minute.\n\n**Test Day Takeaway:** This is a two-step problem: find the volume first, then time $=\\frac{\\text{volume}}{\\text{rate}}$. The $\\pi$ cancels by design.",
